//! What the signed webhook routes call: an HMAC-SHA256 of `"{timestamp}.{raw body}"`, sent as
//! `t=<unix seconds>,v1=<hex>` (Stripe's scheme), with a clock tolerance against replays.
//!
//! @generated by service-builder. Do not edit: changes are overwritten on the next export.

use std::fmt;
use std::time::{SystemTime, UNIX_EPOCH};

use anyhow::Result;
use hmac::{Hmac, KeyInit, Mac};
use sha2::Sha256;

use crate::http::HttpError;

type HmacSha256 = Hmac<Sha256>;

/// Why a signature was refused. The client is only told "invalid signature": which of these it was stays in the logs.
#[derive(Debug, PartialEq, Eq)]
pub enum Refused {
    Missing,
    Malformed,
    /// Further from the clock of the service than the tolerance: a replay, or a clock gone wrong.
    Stale,
    Mismatch,
}

impl fmt::Display for Refused {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.write_str(match self {
            Refused::Missing => "no signature header",
            Refused::Malformed => "malformed signature header",
            Refused::Stale => "timestamp outside the tolerance",
            Refused::Mismatch => "signature does not match",
        })
    }
}

fn mac(secret: &[u8], timestamp: i64, body: &[u8]) -> HmacSha256 {
    // An HMAC key can have any length.
    let mut mac = HmacSha256::new_from_slice(secret).expect("an HMAC key of any size");
    mac.update(timestamp.to_string().as_bytes());
    mac.update(b".");
    mac.update(body);
    mac
}

/// The header a sender would put: `t=<timestamp>,v1=<hex>`.
pub fn sign(secret: &[u8], timestamp: i64, body: &[u8]) -> String {
    format!(
        "t={timestamp},v1={}",
        hex::encode(mac(secret, timestamp, body).finalize().into_bytes())
    )
}

/// Checks `header` against the raw `body`. Several `v1=` are allowed (a secret being rotated): one that
/// matches is enough. The comparison takes the same time whatever the signature.
pub fn verify(
    secret: &[u8],
    header: Option<&str>,
    body: &[u8],
    now: i64,
    tolerance_secs: u32,
) -> Result<(), Refused> {
    let header = header.ok_or(Refused::Missing)?;
    let mut timestamp = None;
    let mut signatures: Vec<Vec<u8>> = Vec::new();
    for part in header.split(',') {
        match part.trim().split_once('=') {
            Some(("t", v)) => timestamp = v.parse::<i64>().ok(),
            Some(("v1", v)) => signatures.extend(hex::decode(v).ok()),
            _ => {}
        }
    }
    let (Some(timestamp), false) = (timestamp, signatures.is_empty()) else {
        return Err(Refused::Malformed);
    };
    if now.abs_diff(timestamp) > u64::from(tolerance_secs) {
        return Err(Refused::Stale);
    }
    // `verify_slice` compares in constant time, and refuses a signature of the wrong length.
    let expected = mac(secret, timestamp, body);
    if signatures.iter().any(|candidate| expected.clone().verify_slice(candidate).is_ok()) {
        Ok(())
    } else {
        Err(Refused::Mismatch)
    }
}

fn now() -> i64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |d| d.as_secs() as i64)
}

/// The secret of a webhook, from the environment. A service that has the route fails at start-up when it is missing.
pub fn secret(env_name: &str) -> Result<Vec<u8>> {
    std::env::var(env_name)
        .map(String::into_bytes)
        .map_err(|_| anyhow::anyhow!("{env_name} is not set: the webhook cannot be verified"))
}

/// The step: a 401, which says nothing about why, unless the signature is good.
pub fn check(env_name: &str, header: Option<&str>, body: &[u8], tolerance_secs: u32) -> Result<()> {
    let secret = secret(env_name)?;
    verify(&secret, header, body, now(), tolerance_secs).map_err(|why| {
        tracing::warn!(%why, "webhook refused");
        HttpError::unauthorized("invalid signature").into()
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    const SECRET: &[u8] = b"whsec_test";
    const BODY: &[u8] = br#"{"type":"payment_intent.succeeded"}"#;

    #[test]
    fn signs_like_any_other_hmac_sha256() {
        // The value comes from a different implementation (Python's hmac): the algorithm is the standard one.
        assert_eq!(
            sign(SECRET, 1_000, BODY),
            "t=1000,v1=562acda52e26a410ff4dd8812edcfff79f73ac7d5fc287b58944c8d2b4e00608"
        );
    }

    #[test]
    fn accepts_a_valid_signature_within_the_tolerance() {
        let header = sign(SECRET, 1_000, BODY);
        assert_eq!(verify(SECRET, Some(&header), BODY, 1_100, 300), Ok(()));
        // Either side of the clock, up to the tolerance included.
        assert_eq!(verify(SECRET, Some(&header), BODY, 1_300, 300), Ok(()));
        assert_eq!(verify(SECRET, Some(&header), BODY, 700, 300), Ok(()));
    }

    #[test]
    fn refuses_a_tampered_body_a_wrong_secret_and_a_replay() {
        let header = sign(SECRET, 1_000, BODY);
        assert_eq!(verify(SECRET, Some(&header), b"{}", 1_000, 300), Err(Refused::Mismatch));
        assert_eq!(verify(b"other", Some(&header), BODY, 1_000, 300), Err(Refused::Mismatch));
        assert_eq!(verify(SECRET, Some(&header), BODY, 1_301, 300), Err(Refused::Stale));
        assert_eq!(verify(SECRET, Some(&header), BODY, 699, 300), Err(Refused::Stale));
        // The timestamp is part of what is signed: moving it breaks the signature.
        let forged = header.replace("t=1000", "t=1001");
        assert_eq!(verify(SECRET, Some(&forged), BODY, 1_001, 300), Err(Refused::Mismatch));
    }

    #[test]
    fn refuses_malformed_or_missing_headers() {
        assert_eq!(verify(SECRET, None, BODY, 1, 300), Err(Refused::Missing));
        for header in ["", "t=1", "v1=00", "v1=zz,t=1", "t=abc,v1=00", "whatever"] {
            assert_eq!(verify(SECRET, Some(header), BODY, 1, 300), Err(Refused::Malformed), "{header}");
        }
        // A signature of the wrong length is a mismatch, not a panic.
        assert_eq!(verify(SECRET, Some("t=1,v1=00"), BODY, 1, 300), Err(Refused::Mismatch));
    }

    #[test]
    fn a_secret_being_rotated_may_sign_twice() {
        let old = sign(b"old", 1_000, BODY);
        let new = sign(SECRET, 1_000, BODY);
        let header = format!("{old},{}", new.split_once(',').unwrap().1);
        assert_eq!(verify(SECRET, Some(&header), BODY, 1_000, 300), Ok(()));
        assert_eq!(verify(b"third", Some(&header), BODY, 1_000, 300), Err(Refused::Mismatch));
    }

    #[test]
    fn the_step_answers_a_401_that_tells_nothing() {
        // SAFETY: only this test touches this variable.
        unsafe { std::env::set_var("EDA_TEST_WEBHOOK_SECRET", "whsec_test") };
        let header = sign(SECRET, now(), BODY);
        assert!(check("EDA_TEST_WEBHOOK_SECRET", Some(&header), BODY, 300).is_ok());
        for bad in [Some("t=1,v1=00"), None] {
            let error = check("EDA_TEST_WEBHOOK_SECRET", bad, BODY, 300).unwrap_err();
            let http = error.downcast_ref::<HttpError>().unwrap();
            assert_eq!((http.status, http.message.as_str()), (401, "invalid signature"));
        }
        // No secret configured: not a 401 the sender could probe, an internal error.
        let error = check("EDA_TEST_NO_SUCH_SECRET", Some(&header), BODY, 300).unwrap_err();
        assert!(error.downcast_ref::<HttpError>().is_none());
    }
}
